// Check if we have approved drafts
// The HTTP Request node returns the array directly in items[0].json
const items = $input.all();

console.log('Filter Approved Drafts - Input items count:', items.length);

if (items.length === 0) {
  console.log('No input items found');
  return [];
}

// Get the response data - HTTP Request returns array directly
const responseData = items[0].json;

console.log('Filter Approved Drafts - Response data type:', typeof responseData);
console.log('Filter Approved Drafts - Is array:', Array.isArray(responseData));

// Handle different response structures
let drafts = [];

if (Array.isArray(responseData)) {
  // Response is already an array
  drafts = responseData;
  console.log('Filter Approved Drafts - Found array with', drafts.length, 'drafts');
} else if (responseData && typeof responseData === 'object') {
  // Response might be wrapped in an object, check common properties
  if (Array.isArray(responseData.data)) {
    drafts = responseData.data;
    console.log('Filter Approved Drafts - Found drafts in data property:', drafts.length);
  } else if (Array.isArray(responseData.drafts)) {
    drafts = responseData.drafts;
    console.log('Filter Approved Drafts - Found drafts in drafts property:', drafts.length);
  } else if (Array.isArray(responseData.items)) {
    drafts = responseData.items;
    console.log('Filter Approved Drafts - Found drafts in items property:', drafts.length);
  } else {
    // Try to find any array property
    const arrayKeys = Object.keys(responseData).filter(key => Array.isArray(responseData[key]));
    if (arrayKeys.length > 0) {
      drafts = responseData[arrayKeys[0]];
      console.log('Filter Approved Drafts - Found drafts in', arrayKeys[0], 'property:', drafts.length);
    } else {
      console.log('Filter Approved Drafts - Response is object but no array found:', Object.keys(responseData));
      // If it's a single draft object, wrap it in array
      if (responseData.id && responseData.status === 'approved') {
        drafts = [responseData];
        console.log('Filter Approved Drafts - Single draft object found, wrapping in array');
      }
    }
  }
}

// Filter only approved drafts and return as individual items
const approvedDrafts = drafts.filter(draft => draft && draft.status === 'approved');

console.log('Filter Approved Drafts - Approved drafts count:', approvedDrafts.length);

if (approvedDrafts.length === 0) {
  console.log('No approved drafts to process');
  return [];
}

// Return each draft as a separate item for processing
return approvedDrafts.map(draft => ({ json: draft }));

// Merge draft, token, and company data
// Get draft data from Filter Approved Drafts node
// Get token data from current item (Get Gmail Token output)
const tokenData = $json;

// Get all drafts from Filter Approved Drafts node
const allDrafts = $('Filter Approved Drafts').all();
const currentCompanyId = tokenData.company_id;

// Find draft matching current company_id
const draft = allDrafts.find(item => 
  item.json.company_id === currentCompanyId
)?.json;

if (!draft) {
  throw new Error(`No draft found for company_id: ${currentCompanyId}`);
}

console.log('Merge Draft & Token - Draft ID:', draft.id);
console.log('Merge Draft & Token - Company ID:', tokenData.company_id);
console.log('Merge Draft & Token - Has access_token:', !!tokenData.access_token);

// Validate token data
if (!tokenData || !tokenData.access_token) {
  throw new Error('Access token is missing from token response');
}

// Merge: combine draft data with token data
const merged = {
  draft_id: draft.id,
  draft_subject: draft.subject,
  draft_body: draft.body,
  draft_email_id: draft.email_id,
  company_id: tokenData.company_id,
  company_email: tokenData.company_email,
  access_token: tokenData.access_token,
  expires_at: tokenData.expires_at
};

if (!merged.draft_id || !merged.draft_email_id) {
  throw new Error('Draft data incomplete - missing draft_id or email_id');
}

if (!merged.access_token) {
  throw new Error('Access token missing - cannot send email');
}

console.log('Merge Draft & Token - Successfully merged');
return merged;

// Prepare email data for Gmail API
// Get email data from current item (Get Email Info output)
const email = $json;
// Get merged draft & token data from Merge Draft & Token node
const merged = $('Merge Draft & Token').item.json;

console.log('Prepare Email Message - Email data:', JSON.stringify({
  email_id: email.id,
  from_email: email.from_email,
  thread_id: email.thread_id
}, null, 2));

console.log('Prepare Email Message - Merged data:', JSON.stringify({
  draft_id: merged.draft_id,
  draft_subject: merged.draft_subject,
  company_id: merged.company_id,
  has_access_token: !!merged.access_token
}, null, 2));

// Validate required data
if (!email || !email.from_email) {
  throw new Error('Email data is missing or invalid');
}

if (!merged || !merged.draft_id || !merged.draft_subject || !merged.draft_body) {
  throw new Error('Draft data is missing or invalid');
}

if (!merged.access_token) {
  throw new Error('Access token missing - cannot send email');
}

// Build email message
const toEmail = email.from_email;
const subject = merged.draft_subject;
const body = merged.draft_body;
const threadId = email.thread_id || null;
const fromEmail = merged.company_email;

// Create email message in RFC 2822 format
const message = [
  `From: ${fromEmail}`,
  `To: ${toEmail}`,
  `Subject: ${subject}`,
  `Content-Type: text/plain; charset=utf-8`,
  '',
  body
].join('\n');

// Encode message in base64url format (Gmail API requires this)
const encodedMessage = Buffer.from(message)
  .toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=+$/, '');

const result = {
  draft_id: merged.draft_id,
  company_id: merged.company_id,
  access_token: merged.access_token,
  to: toEmail,
  subject: subject,
  body: body,
  thread_id: threadId,
  raw_message: encodedMessage
};

console.log('Prepare Email Message - Result:', JSON.stringify({
  draft_id: result.draft_id,
  to: result.to,
  subject: result.subject,
  has_thread_id: !!result.thread_id,
  has_access_token: !!result.access_token
}, null, 2));

return result;

// Prepare Gmail API request body
const emailData = $json;

console.log('Prepare Gmail Request - Email data:', JSON.stringify({
  draft_id: emailData.draft_id,
  to: emailData.to,
  subject: emailData.subject,
  has_thread_id: !!emailData.thread_id,
  has_raw_message: !!emailData.raw_message,
  has_access_token: !!emailData.access_token
}, null, 2));

// Validate required fields
if (!emailData.raw_message) {
  throw new Error('raw_message is missing');
}

if (!emailData.access_token) {
  throw new Error('access_token is missing');
}

// Build Gmail API request body
// Gmail API expects: { raw: "base64url_encoded_message", threadId?: "thread_id" }
const requestBody = {
  raw: emailData.raw_message
};

// Only add threadId if it exists and is not null/empty
if (emailData.thread_id && emailData.thread_id.trim() !== '') {
  requestBody.threadId = emailData.thread_id;
  console.log('Prepare Gmail Request - Including threadId:', emailData.thread_id);
} else {
  console.log('Prepare Gmail Request - No threadId (new conversation)');
}

console.log('Prepare Gmail Request - Request body:', JSON.stringify({
  has_raw: !!requestBody.raw,
  has_threadId: !!requestBody.threadId,
  raw_length: requestBody.raw ? requestBody.raw.length : 0
}, null, 2));

// Return data for HTTP Request node
return {
  draft_id: emailData.draft_id,
  company_id: emailData.company_id,
  access_token: emailData.access_token,
  gmail_request_body: requestBody,
  gmail_request_body_json: JSON.stringify(requestBody)
};

// Preserve draft_id after Gmail API call
// Gmail API response doesn't include draft_id, so get it from previous node
const gmailResponse = $json; // Current item (Gmail API response)
const originalData = $('Prepare Gmail Request Body').item.json; // Original data with draft_id

console.log('Preserve Draft ID - Gmail response:', JSON.stringify({
  has_id: !!gmailResponse.id,
  has_threadId: !!gmailResponse.threadId
}, null, 2));

console.log('Preserve Draft ID - Original data:', JSON.stringify({
  draft_id: originalData.draft_id,
  company_id: originalData.company_id
}, null, 2));

// Merge: use Gmail response but preserve draft_id from original data
return {
  draft_id: originalData.draft_id,
  company_id: originalData.company_id,
  gmail_message_id: gmailResponse.id || null,
  gmail_thread_id: gmailResponse.threadId || null
};
